struct Csc {
    int rows{};
    int columns{};
    std::vector<int> indices{};
    std::vector<int> offsets{};
    std::vector<double> values{};

    CscAbi abi() {
        return {
            rows,
            columns,
            static_cast<int>(values.size()),
            indices.data(),
            offsets.data(),
            values.data(),
        };
    }
};

struct Triplet {
    int row;
    int column;
    double value;
};

