#pragma once
// Updated before each retained graph replay; never capture these as constants.
struct QocoIpmParameters {
    double k, kinv, absolute, relative, inaccurate_absolute, inaccurate_relative;
    double ir_tolerance;
    int maximum, ir_maximum;
    double dynamic_reg;
    int warm_start;
    int update_invalid;
};
static __global__ void qoco_ipm_parameters_set(QocoIpmParameters* target, QocoIpmParameters value) {
    *target = value;
}
static __global__ void qoco_ipm_scale(double* values, int count, const QocoIpmParameters* p) {
    for (int i = blockIdx.x * blockDim.x + threadIdx.x; i < count; i += blockDim.x * gridDim.x)
        values[i] = __dmul_rn(values[i], p->kinv);
}

static __global__ void qoco_ipm_parameters_from_update(QocoIpmParameters* target,
    QocoIpmParameters value, const double* update) {
    value.k=update[0]; value.kinv=update[1];
    value.update_invalid=update[8]!=0 || !isfinite(value.k) || !isfinite(value.kinv);
    *target=value;
}

__global__ void qoco_ipm_update_guard(const QocoIpmParameters* p,
    cudaGraphConditionalHandle handle,QocoGpuCompletion* result) {
    cudaGraphSetConditional(handle,!p->update_invalid);
    if (p->update_invalid) *result={1,QOCO_NUMERICAL_ERROR,0,0,0,0,
        INFINITY,INFINITY,INFINITY,NAN,p->dynamic_reg};
}
