#include <cuda_runtime.h>
#include <cmath>
#include <cstdio>
#include <cstdlib>
#include "qoco_gpu_replay.h"
#include "qoco_ipm_parameters.cuh"
#define REQUIRE(x) do { if(!(x)) { std::fprintf(stderr,"line %d: %s\n",__LINE__,#x); std::exit(1); }} while(0)
#define CUDA(x) REQUIRE((x)==cudaSuccess)

__global__ void qoco_ipm_update_guard(const QocoIpmParameters* p,
    cudaGraphConditionalHandle handle,QocoGpuCompletion* result) {
    cudaGraphSetConditional(handle,!p->update_invalid);
    if (p->update_invalid) *result={1,QOCO_NUMERICAL_ERROR,0,0,0,0,
        INFINITY,INFINITY,INFINITY,NAN,p->dynamic_reg};
}
__global__ void body(QocoGpuCompletion* result,int* count) { ++*count; result->status=QOCO_SOLVED; }
int main() {
 cudaStream_t stream; CUDA(cudaStreamCreateWithFlags(&stream,cudaStreamNonBlocking));
 QocoIpmParameters* params; QocoGpuCompletion* result; double* input; int* count;
 CUDA(cudaMalloc(&params,sizeof(*params))); CUDA(cudaMalloc(&result,sizeof(*result)));
 CUDA(cudaMalloc(&input,9*sizeof(double))); CUDA(cudaMalloc(&count,sizeof(int)));
 CUDA(cudaMemsetAsync(count,0,sizeof(int),stream));
 CUDA(cudaMemsetAsync(result,0,sizeof(*result),stream));
 CUDA(cudaMemsetAsync(params,0,sizeof(*params),stream));
 CUDA(cudaStreamSynchronize(stream));
 cudaGraph_t graph; CUDA(cudaGraphCreate(&graph,0)); cudaGraphConditionalHandle handle;
 CUDA(cudaGraphConditionalHandleCreate(&handle,graph,1,cudaGraphCondAssignDefault));
 CUDA(cudaStreamBeginCaptureToGraph(stream,graph,nullptr,nullptr,0,cudaStreamCaptureModeThreadLocal));
 QocoIpmParameters initial{}; initial.dynamic_reg=1e-9;
 qoco_ipm_parameters_from_update<<<1,1,0,stream>>>(params,initial,input);
 qoco_ipm_update_guard<<<1,1,0,stream>>>(params,handle,result);
 size_t n{}; const cudaGraphNode_t* deps{}; cudaStreamCaptureStatus status; unsigned long long id; cudaGraph_t captured;
 CUDA(cudaStreamGetCaptureInfo_v2(stream,&status,&id,&captured,&deps,&n));
 cudaGraphNodeParams p{}; p.type=cudaGraphNodeTypeConditional; p.conditional.handle=handle;
 p.conditional.type=cudaGraphCondTypeIf; p.conditional.size=1; cudaGraphNode_t node;
 CUDA(cudaGraphAddNode(&node,graph,deps,n,&p));
 CUDA(cudaStreamUpdateCaptureDependencies(stream,&node,1,cudaStreamSetCaptureDependencies));
 CUDA(cudaStreamEndCapture(stream,&captured));
 CUDA(cudaStreamBeginCaptureToGraph(stream,p.conditional.phGraph_out[0],nullptr,nullptr,0,cudaStreamCaptureModeThreadLocal));
 body<<<1,1,0,stream>>>(result,count);
 CUDA(cudaStreamEndCapture(stream,&captured));
 cudaGraphExec_t executable; CUDA(cudaGraphInstantiate(&executable,graph,0));
 int accepted=0,cases=0;
 for (int repeat=0;repeat<8;++repeat) for (int test=0;test<8;++test) {
  double values[9]{2,.5,0,1,0,1,0,1,0};
  if(test==1) values[8]=1; if(test==2) values[8]=NAN;
  if(test==3) values[0]=NAN; if(test==4) values[1]=INFINITY;
  if(test==5) values[0]=-INFINITY; if(test==6) values[1]=NAN;
  const bool valid=test==0 || test==7;
  CUDA(cudaMemcpyAsync(input,values,sizeof(values),cudaMemcpyHostToDevice,stream));
  CUDA(cudaGraphLaunch(executable,stream));
  QocoGpuCompletion got{}; int observed=0;
  CUDA(cudaMemcpyAsync(&got,result,sizeof(got),cudaMemcpyDeviceToHost,stream));
  CUDA(cudaMemcpyAsync(&observed,count,sizeof(int),cudaMemcpyDeviceToHost,stream));
  CUDA(cudaStreamSynchronize(stream)); accepted+=valid;
  REQUIRE(observed==accepted && got.status==(valid ? QOCO_SOLVED : QOCO_NUMERICAL_ERROR));
  if(!valid) REQUIRE(got.abi_version==1 && got.iterations==0 && !std::isfinite(got.primal_residual));
  ++cases;
 }
 CUDA(cudaGraphExecDestroy(executable)); CUDA(cudaGraphDestroy(graph));
 CUDA(cudaFree(params)); CUDA(cudaFree(result)); CUDA(cudaFree(input)); CUDA(cudaFree(count)); CUDA(cudaStreamDestroy(stream));
 std::printf("PASS: %d device scale/invalid guard cases, conditional body skipped on invalid update\n",cases);
}

